@Mod.EventBusSubscriber(modid="epiccompat_parcool", bus=Mod.EventBusSubscriber.Bus.FORGE, value={Dist.CLIENT})
public class PlayerHandler {
    @SubscribeEvent
    public static void onTickLocal(TickEvent.PlayerTickEvent event) {
        IParkourPlayerPatch parkourPlayer;
        if (event.player.m_7578_() && (parkourPlayer = (IParkourPlayerPatch)ClientEngine.getInstance().getPlayerPatch()) != null) {
            Parkourability parkourAbility = Parkourability.get((Player)event.player);
            if (parkourAbility != null) {
                for (Action action : parkourAbility.getList()) {
                    if (action instanceof FastRun || !action.isDoing()) continue;
                    if (!parkourPlayer.isParkourActive()) {
                        parkourPlayer.setParkourActive(true);
                        NetworkManager.sendToServer(new CPSetParkourActive(true));
                    }
                    return;
                }
            }
            if (parkourPlayer.isParkourActive()) {
                parkourPlayer.setParkourActive(false);
                NetworkManager.sendToServer(new CPSetParkourActive(false));
            }
        }
    }
}

