ForgeConfigSpec.Builder COMMON_BUILDER = new ForgeConfigSpec.Builder();
COMMON_BUILDER.comment("Game settings").push(CATEGORY_SETTINGS);
ENABLE_FARMERS_BUY_FD_CROPS = COMMON_BUILDER.comment("If enabled, Novice and Apprentice Farmer villagers will have a chance to buy crops from this mod.").define("enableFarmerFDTrades", true);
ENABLE_WANDERING_TRADER_SELLS_FD_ITEMS = COMMON_BUILDER.comment("If enabled, the Wandering Trader will have a chance to sell seeds and plantables from this mod.").define("enableWanderingTraderFDTrades", true);
ENABLE_ROPE_REELING = COMMON_BUILDER.comment("If enabled, players will be able to reel back rope, bottom to top, when sneak-using with an empty hand on them.").define("enableRopeReeling", true);
CANVAS_SIGN_DARK_BACKGROUND_LIST = COMMON_BUILDER.comment(new String[]{"A list of dye colors that, when used as the background color of a Canvas Sign, should default to white text when placed.", "Dyes: [\"white\", \"orange\", \"magenta\", \"light_blue\", \"yellow\", \"lime\", \"pink\", \"gray\", \"light_gray\", \"cyan\", \"purple\", \"blue\", \"brown\", \"green\", \"red\", \"black\"]"}).defineList("canvasSignDarkBackgroundList", (List)ImmutableList.of((Object)"gray", (Object)"purple", (Object)"blue", (Object)"brown", (Object)"green", (Object)"red", (Object)"black"), obj -> true);
COMMON_BUILDER.pop();
COMMON_BUILDER.comment("Farming").push(CATEGORY_FARMING);
